def idempotent_run(op_store, store, path, tenant_id, operator, body, key,
                   validator, executor, decoder=None, artifact_store=None):
    """CLI counterpart of the HTTP idempotency guard.

    Returns a process exit code. ``validator()`` runs cheap side-effect-free
    request checks *before* the binding lookup and returns None on success or
    an ``(exit_code, message)`` refusal (a refusal is never audited and never
    consumes the key). ``decoder`` (when given) performs the side-effect-free
    but expensive validation -- bundle decryption -- *after* an already-bound
    key has been replayed/conflicted but *before* a new key is bound, so a
    wrong passphrase neither masks a replay nor consumes the key.
    ``executor(operation, mirror) -> (http_status, body)`` runs once for a new
    binding and may raise ProviderInvalidMaterial / ProviderUnavailable /
    LedgerError / LockTimeout.
    """
    if _idem_key_error(key):
        return 2
    normalized = operations_mod.normalize_body(body)

    refusal = validator()
    if refusal is not None:
        code, message = refusal
        return _fail(message, code)

    # An already-bound key replays/conflicts before the expensive decoder
    # (bundle decryption), so a bad passphrase on a retry never masks a
    # replay or consumes the key.
    peek = op_store.peek(tenant_id, operator, path, normalized, key)
    existing = _idem_serve_existing(op_store, peek.kind, peek.record)
    if existing is not None:
        return existing

    if decoder is not None:
        refusal = decoder()
        if refusal is not None:
            code, message = refusal
            return _fail(message, code)

    # begin() is authoritative for the bind (another process may have won
    # between the peek and here).
    begin = op_store.begin(tenant_id, operator, path, normalized, key)
    if begin.kind == "conflict":
        return _idem_serve_existing(op_store, "conflict", begin.record)
    if begin.kind == "replay":
        if begin.record.is_terminal():
            return _idem_serve_existing(op_store, "replay", begin.record)
        # Still pending: take a stranded attempt over immediately; if a live
        # owner (thread or process) holds the claim, wait for its terminal.
        if artifact_store is not None:
            try:
                return _run_owned_attempt(
                    op_store, store, artifact_store, executor,
                    begin.record, blocking=False, takeover=True,
                )
            except BlockingIOError:
                return _idem_wait_then_serve(op_store, begin.record)
        return _idem_wait_then_serve(op_store, begin.record)

    operation = begin.record
    return _run_owned_attempt(
        op_store, store, artifact_store, executor, operation,
        blocking=True, takeover=False,
    )


def _idempotent_run_body(op_store, store, artifact_store, executor, operation,
                         op_id, mirror):
    from .artifacts import ArtifactStrandUnavailable

    try:
        http_status, resp = executor(operation, mirror)
    except ArtifactStrandUnavailable as exc:
        # The mirror could not be described/tied in before the first provider
        # call: nothing committed, keep the operation pending for a same-id
        # retry (exit 1).
        return _emit_operation_result(
            exc.http_status, _strand_unavailable_body(op_id)
        )
    except LockTimeout:
        body_err = {
            "error": "operation timed out waiting for a lock",
            "operation_id": op_id,
        }
        op_store.finish(
            operation, operations_mod.STATUS_TIMED_OUT, 503, body_err
        )
        return _emit_operation_result(503, body_err)
    except ProviderInvalidMaterial as exc:
        try:
            http_status, body_err = _provider_terminal(
                op_store, store, operation, 400, str(exc)
            )
            return _emit_operation_result(http_status, body_err)
        except (OSError, LedgerError) as persist_exc:
            body_err = {
                "error": _ledger_failure_text(persist_exc),
                "operation_id": op_id,
            }
            op_store.finish(
                operation, operations_mod.STATUS_FAILED, 500, body_err
            )
            return _emit_operation_result(500, body_err)
    except ProviderReconnectPending:
        # The provider was never effectively called (gate timeout or a
        # displaced provider_id): the store/restore abort path already removed
        # the empty journal and minted no handle. Reset the mirror to a clean
        # bound strand and leave the operation PENDING for a same-id retry,
        # answering the fixed safe 503 (exit 1) without a duplicate event.
        if mirror is not None:
            try:
                mirror.reset_for_pending_retry()
            except OSError:
                pass
        return _emit_operation_result(
            503,
            {
                "error": "key management provider is unavailable",
                "operation_id": op_id,
            },
        )
    except ProviderUnavailable:
        try:
            http_status, body_err = _provider_terminal(
                op_store, store, operation, 503,
                "key management provider is unavailable",
            )
            return _emit_operation_result(http_status, body_err)
        except (OSError, LedgerError) as persist_exc:
            body_err = {
                "error": _ledger_failure_text(persist_exc),
                "operation_id": op_id,
            }
            op_store.finish(
                operation, operations_mod.STATUS_FAILED, 500, body_err
            )
            return _emit_operation_result(500, body_err)
    except OSError as exc:
        # A pre-commit staging/write failure happened before the commit-point
        # append: file and handles were rolled back, nothing committed.
        # Finalize failed(500).
        body_err = {
            "error": "audit ledger failure: %s" % exc,
            "operation_id": op_id,
        }
        op_store.finish(operation, operations_mod.STATUS_FAILED, 500, body_err)
        return _emit_operation_result(500, body_err)
    except LedgerError:
        body_err = {
            "error": "audit ledger is unavailable",
            "operation_id": op_id,
        }
        op_store.finish(operation, operations_mod.STATUS_FAILED, 500, body_err)
        return _emit_operation_result(500, body_err)
    resp = dict(resp)
    resp["operation_id"] = op_id
    state = operations_mod.state_for_http_status(http_status)
    op_store.finish(operation, state, http_status, resp)
    if artifact_store is not None and mirror is not None:
        # Committed: verified ownership then dropped; uncommitted: dropped
        # only once every rollback artifact is gone. A mirror that cannot be
        # verified survives for the next startup.
        artifact_store.after_terminal(mirror)
    return _emit_operation_result(http_status, resp)


def main(argv: Optional[List[str]] = None) -> int:
    """CLI entry point; returns a process exit code.

    A KMS/HSM backend failure maps to exit code 1 (HTTP 503) with a generic
    message; malformed imported material maps to exit code 2 (HTTP 400).
    """
    try:
        return _run(argv)
    except ProviderInvalidMaterial as exc:
        return _fail(str(exc), 2)
    except ProviderUnavailable:
        # Generic wording: never print a handle or material in the error.
        return _fail("key management provider is unavailable", 1)

def _surviving_artifacts_consistent(self, descriptor: dict) -> bool:
    """Whether every surviving on-disk reference cross-agrees.

    Returns False when a surviving reference is missing, corrupt,
    duplicated or carries more/fewer facts than the mirror; the caller
    then keeps the whole evidence set. Absence of an artifact the attempt
    legitimately removed is fine.
    """
    try:
        self._journal_verdict(descriptor)
        kind = descriptor.get("kind")
        if kind == "batch_rotate":
            self._snapshot_verdict(descriptor)
        elif descriptor.get("snapshot"):
            return False
        if kind == "restore":
            self._restore_artifacts_verdict(descriptor)
        elif isinstance(descriptor.get("empty_marker"), str):
            return False
    except ArtifactInconsistent:
        return False
    return True

def _journal_verdict(self, descriptor: dict) -> None:
    """Cross-check a surviving provision journal against the mirror.

    Compares the journal's operation header (operation_id/tenant/action)
    and its exact provider_id/handle SET with the mirror: a corrupt,
    duplicated or extra entry is an inconsistency. Legacy headerless
    journals keep id-only resolution, but their handle set must still
    equal the mirror's. Absence is fine. Raises ArtifactInconsistent.
    """
    operation_id = descriptor["operation_id"]
    journal_id = descriptor.get("journal") or operation_id
    path = self.key_store._provision_path(journal_id)
    if not os.path.exists(path):
        return
    try:
        with open(path, "r", encoding="utf-8") as fh:
            raw_lines = [
                line for line in fh.read().splitlines() if line.strip()
            ]
    except OSError as exc:
        raise ArtifactInconsistent(str(exc))
    entries = []
    header = None
    for index, raw in enumerate(raw_lines):
        try:
            line = json.loads(raw)
        except ValueError:
            raise ArtifactInconsistent("corrupt provision journal line")
        if not isinstance(line, dict):
            raise ArtifactInconsistent(
                "provision journal line is not an object"
            )
        if index == 0 and "operation_id" in line:
            header = line
            continue
        provider_id = line.get("provider_id")
        handle = line.get("handle")
        if not (
            isinstance(provider_id, str)
            and provider_id
            and isinstance(handle, str)
            and handle
        ):
            raise ArtifactInconsistent("provision journal entry is malformed")
        entries.append((provider_id, handle))
    kind = descriptor.get("kind")
    if header is not None:
        if header.get("operation_id") != journal_id:
            raise ArtifactInconsistent(
                "provision journal header names another operation"
            )
        if kind is not None:
            if header.get("tenant_id") != descriptor.get("tenant_id"):
                raise ArtifactInconsistent(
                    "provision journal tenant disagrees with the mirror"
                )
            if header.get("action") != descriptor.get("action"):
                raise ArtifactInconsistent(
                    "provision journal action disagrees with the mirror"
                )
    pairs = set()
    for pair in entries:
        if pair in pairs:
            raise ArtifactInconsistent(
                "duplicate handle entry in provision journal"
            )
        pairs.add(pair)
    mirrored = {
        (entry.get("provider_id"), entry.get("handle"))
        for entry in descriptor.get("handles", [])
        if isinstance(entry, dict)
    }
    if pairs != mirrored:
        raise ArtifactInconsistent(
            "provision journal handle set disagrees with the mirror"
        )

@staticmethod
def _marker_event_id(marker) -> Optional[str]:
    """The event id a (possibly nested) pending marker names."""
    if not isinstance(marker, dict):
        return None
    nested = marker.get("event")
    desc = nested if isinstance(nested, dict) else marker
    event_id = desc.get("event_id") if isinstance(desc, dict) else None
    return event_id if isinstance(event_id, str) else None

def _scan_pending_markers(self, operation_id: str) -> list:
    """All surviving pending markers (key files, policy doc) naming an id."""
    found = []
    try:
        names = os.listdir(self.data_dir)
    except OSError:
        return found
    for name in names:
        if not (name.endswith(".json") and _is_key_id(name[:-5])):
            continue
        record = self.key_store._read_record(os.path.join(self.data_dir, name))
        marker = getattr(record, "pending_event", None)
        if isinstance(marker, dict) and self._marker_event_id(
            marker
        ) == operation_id:
            found.append(("key", record.key_id, marker))
    policy_dir = os.path.join(self.data_dir, "policies")
    try:
        policy_names = os.listdir(policy_dir)
    except OSError:
        return found
    for name in policy_names:
        if not name.endswith(".json"):
            continue
        path = os.path.join(policy_dir, name)
        doc = self._read_policy_doc(path)
        owner = None
        pending = None
        if doc is None:
            try:
                with open(path, "r", encoding="utf-8") as fh:
                    raw = json.load(fh)
            except (OSError, ValueError):
                continue
            if isinstance(raw, dict):
                owner = raw.get("tenant_id")
                pending = raw.get("pending_event")
        else:
            owner, pending = doc
        if isinstance(pending, dict) and self._marker_event_id(
            pending
        ) == operation_id:
            found.append(("policy", owner, pending))
    return found

def _snapshot_verdict(self, descriptor: dict) -> None:
    """Cross-check a surviving batch snapshot against the mirror.

    Filename/event id, tenant, the exact key_id set, and every
    ``previous_b64`` image (strictly decoded into a tenant-matching,
    version-contiguous KeyRecord with no pending marker) must agree with
    the mirror and with every residual batch marker. A surviving snapshot
    the mirror never named, or a referenced but corrupt/mismatched one,
    is an inconsistency.
    """
    operation_id = descriptor["operation_id"]
    tenant_id = descriptor.get("tenant_id")
    referenced = descriptor.get("snapshot")
    expected_id = referenced or operation_id
    path = self.key_store._batch_snapshot_path(expected_id)
    present = os.path.exists(path)
    if referenced is None:
        if present:
            raise ArtifactInconsistent(
                "unnamed batch snapshot survives for the operation"
            )
        return
    if not present:
        # Referenced but gone: legitimate only after a verified rollback;
        # the residual-marker scan decides whether files still need it.
        return
    raw = self.key_store._read_batch_snapshot(expected_id)
    if not isinstance(raw, dict):
        raise ArtifactInconsistent("batch snapshot is missing or corrupt")
    if raw.get("event_id") != expected_id:
        raise ArtifactInconsistent(
            "batch snapshot event_id disagrees with its filename"
        )
    if raw.get("tenant_id") != tenant_id:
        raise ArtifactInconsistent(
            "batch snapshot tenant disagrees with the mirror"
        )
    snapshot_keys = set()
    for entry in raw.get("keys", []):
        if not isinstance(entry, dict) or not _is_key_id(entry.get("key_id")):
            raise ArtifactInconsistent("batch snapshot key entry is malformed")
        snapshot_keys.add(entry["key_id"])
    if snapshot_keys != set(descriptor.get("write_set", [])):
        raise ArtifactInconsistent(
            "batch snapshot key set disagrees with the mirror write set"

    def _residual_evidence(self, descriptor: dict) -> bool:
        """Whether uncommitted-attempt artifacts still survive on disk.

        Scans the provision journal, the batch snapshot, the restore empty
        marker and every key/policy file carrying a pending marker named after
        this operation. The outbox recovery leaves these in place exactly while
        it is parking the scene (unreadable ledger, unreachable provider,
        corrupt/missing basis, id collision); while any survives the mirror
        cannot be dropped.
        """
        operation_id = descriptor["operation_id"]
        journal_id = descriptor.get("journal") or operation_id
        if os.path.exists(self.key_store._provision_path(journal_id)):
            return True
        if descriptor.get("kind") == "migrate" and os.path.exists(
            self.key_store._migration_path(operation_id)
        ):
            # A surviving migration snapshot means the scene is intentionally
            # preserved: an uncommitted move still owes its file restore/new
            # handle delete, or a committed one still owes old-handle cleanup.
            return True
        if descriptor.get("snapshot") and os.path.exists(
            self.key_store._batch_snapshot_path(descriptor["snapshot"])
        ):
            return True
        empty_marker = descriptor.get("empty_marker")
        if isinstance(empty_marker, str) and self._pending_empty_marker(
            empty_marker, operation_id
        ):
            return True
        return bool(self._scan_pending_markers(operation_id))

    def _pending_empty_marker(self, path: str, operation_id: str) -> bool:
        """An empty-restore marker still carrying THIS pending event."""
        try:
            with open(path, "r", encoding="utf-8") as fh:
                marker = json.load(fh)
        except (OSError, ValueError):
            # Corrupt marker reference: treat as residual evidence so the
            # mirror (and the marker) stay for a later, safer open.
            return os.path.exists(path)
        if not isinstance(marker, dict):
            return os.path.exists(path)
        event = marker.get("event")
        if isinstance(event, dict):
            return event.get("event_id") == operation_id
        return False


