         ("h", "peer")),
        (_EmptyOut(_ops("transfer_out", "transfer_in")), "transfer_out",
         ("h", "peer")),
        (_BadInKeys(_ops("transfer_out", "transfer_in")), "transfer_in",
         ("peer", b"x")),
